def stake_sold(amount_raised, pre_money):
    post_money = pre_money + amount_raised
    return amount_raised / post_money

rounds = {
    "Seed": (50_000_000, 200_000_000),
    "Series A": (120_000_000, 600_000_000),
}

for name, (raised, pre) in rounds.items():
    share = stake_sold(raised, pre)
    print(f"{name}: investors bought {share:.1%}")
